import java.io.InputStream;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inStream = System.in;
        Scanner scanner = new Scanner(inStream);
        int n = scanner.nextInt();
        int answer = new Computation().calculate(n);
        System.out.print(answer);
        scanner.close();
    }

    static class Computation {
        int calculate(int n) {
            int[][][] dp = new int[2 * n + 1][2 * n + 1][2];
            dp[0][0][0] = 1;
            for (int depth = 1; depth <= 2 * n; depth++) {
                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    if (opened - 1 >= 0) {
                        dp[depth][opened][0] += dp[depth - 1][opened - 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened - 1][0];
                    }
                    if (opened + 1 <= n) {
                        dp[depth][opened][0] += dp[depth - 1][opened + 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened + 1][0];
                    }
                    dp[depth][opened][0]++;
                    dp[depth][opened][0] %= 1_000_000_007;
                    dp[depth][opened][1] %= 1_000_000_007;
                }
            }
            return dp[2 * n][0][1];
        }
    }
}
