#include <iostream>
#include <vector>

int main() {
    int n;
    std::cin >> n;
    std::vector<std::vector<std::vector<long long>>> dp(2 * n + 1, std::vector<std::vector<long long>>(2 * n + 1, std::vector<long long>(2, 0)));
    dp[0][0][0] = 1;
    const long long MOD = 1000000007;

    for (int depth = 1; depth <= 2 * n; ++depth) {
        for (int opened = (depth & 1); opened <= depth; opened += 2) {
            if (opened - 1 >= 0) {
                dp[depth][opened][0] += dp[depth - 1][opened - 1][1];
                dp[depth][opened][1] += dp[depth - 1][opened - 1][0];
            }
            if (opened + 1 <= n) {
                dp[depth][opened][0] += dp[depth - 1][opened + 1][1];
                dp[depth][opened][1] += dp[depth - 1][opened + 1][0];
            }
            dp[depth][opened][0] = (dp[depth][opened][0] + 1) % MOD;
            dp[depth][opened][1] %= MOD;
        }
    }
    std::cout << dp[2 * n][0][1] << std::endl;
    return 0;
}
